// The agent ends every reply with a STATUS block. Parse it here so the branches
// below are deterministic instead of trusting the agent to call the right tool.
const reply = String($json.output ?? $json.text ?? '');

// [ \t]* rather than \s*, so an empty label does not swallow the next line.
const field = (label) => {
  const m = reply.match(new RegExp('^[ \\t]*' + label + ':[ \\t]*([^\\n\\r]*)', 'mi'));
  return m ? m[1].trim() : '';
};

const raw = field('STATUS').toLowerCase();
const status = ['changed', 'unresolved', 'answered'].includes(raw) ? raw : 'answered';

return [{
  json: {
    status,
    sku: field('SKU'),
    attribute: field('FIELD'),
    oldValue: field('OLD'),
    newValue: field('NEW'),
    reason: field('REASON'),
    answer: reply.replace(/^[ \t]*(STATUS|SKU|FIELD|OLD|NEW|REASON):[^\n\r]*$/gim, '').trim(),
  },
}];
